/**
 * Writes the footer chart's generated files from `geo.ts` + `chart.ts` (see `render.ts`):
 *
 *   npx vite-node components/site/footer/tools/build-chart.ts
 *   npx prettier --write components/site/footer/strait-data.ts
 *
 * Run it after changing the shores, the landmarks, the view or the drawing; `chart.test.ts`
 * fails while the committed files are stale.
 */
import { writeFileSync } from "node:fs";
import path from "node:path";
import { buildChart } from "../chart";
import { chartSvg, transitData } from "../render";

const dir = path.join(process.cwd(), "components/site/footer");
const c = buildChart();
const d = transitData(c);

writeFileSync(path.join(dir, "strait-chart.svg"), chartSvg(c));

const types: Record<keyof typeof d, string> = {
  VIEW: "{ width: number; height: number }",
  ROUTE: "readonly number[]",
  TRAFFIC: "readonly number[]",
  FRAME: "readonly number[]",
  WIDTHS: "readonly number[]",
  SHIP: "Pose",
  AMBIENT: "readonly Pose[]",
  LABELS: "readonly ChartLabel[]",
  TICKS: "readonly { text: string; at: Pt }[]",
  FURNITURE: "{ compass: Pt; scale: { x0: number; x1: number; y: number; nm: number } }",
};
const docs: Record<keyof typeof d, string> = {
  VIEW: "The chart's viewBox.",
  ROUTE: "The tanker's track, x y pairs: southbound lane, Black Sea entrance → off Maiden's Tower.",
  TRAFFIC: "The ambient ships' track, x y pairs: northbound lane, Marmara → Black Sea.",
  FRAME:
    "Streak frame, north → south: cx cy hx hy per station (centre, capped half-width toward Asia).",
  WIDTHS: "Channel width at each frame station, km.",
  SHIP: "The tanker at rest (the end of ROUTE).",
  AMBIENT: "The ambient ships at rest.",
  LABELS: "Chart labels (HTML over the drawing), anchors in view units.",
  TICKS: "Graticule labels.",
  FURNITURE: "Compass and two-mile scale positions (drawn in the SVG, labelled in HTML).",
};
const body = (Object.keys(d) as (keyof typeof d)[])
  .map((k) => `/** ${docs[k]} */\nexport const ${k}: ${types[k]} = ${JSON.stringify(d[k])};`)
  .join("\n\n");
writeFileSync(
  path.join(dir, "strait-data.ts"),
  `/* Generated by components/site/footer/tools/build-chart.ts from geo.ts and chart.ts — do not
   edit by hand; chart.test.ts checks it is current. */
import type { ChartLabel, Pose, Pt } from "./chart";

${body}
`
);
console.log("wrote strait-chart.svg and strait-data.ts");
